import{_ as l,a0 as a,w as p,s,I as n,x as o,a1 as i,A as r,ao as g}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"嘗試 H2o 做機器學習 | LCTT x X-CMD","titleTemplate":false,"description":"嘗試 H2o 做機器學習 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"嘗試 H2o 做機器學習 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"嘗試 H2o 做機器學習 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180314 Playing with water","title":"嘗試 H2o 做機器學習","tag":"201804","desc":""},"relativePath":"201804/20180314 Playing with water.md","filePath":"[post].md"}'),d={name:"201804/20180314 Playing with water.md"};function m(w,t,u,f,T,H){const e=a("Link");return p(),s("div",null,[t[18]||(t[18]=n("h1",{id:"嘗試-h2o-做機器學習",tabindex:"-1"},[o("嘗試 H2o 做機器學習 "),n("a",{class:"header-anchor",href:"#嘗試-h2o-做機器學習","aria-label":"Permalink to “嘗試 H2o 做機器學習”"},"​")],-1)),t[19]||(t[19]=n("p",null,[n("img",{src:"https://veronneau.org/media/blog/2018-03-14/h2o_job.png",alt:"H2o Flow gradient boosting job",title:"H2o Flow gradient boosting job"})],-1)),n("p",null,[t[2]||(t[2]=o("我目前正在參加一個機器學習班，雖然工作量很瘋狂，但我非常喜歡。我最初計劃使用 ",-1)),i(e,{href:"https://en.wikipedia.org/wiki/R_(programming_language)"},{default:r(()=>[...t[0]||(t[0]=[o("R",-1)])]),_:1}),t[3]||(t[3]=o(" 來訓練我的資料庫，但老師建議我使用一個 FOSS 機器學習框架 ",-1)),i(e,{href:"https://www.h2o.ai"},{default:r(()=>[...t[1]||(t[1]=[o("H2o",-1)])]),_:1}),t[4]||(t[4]=o("。",-1))]),t[20]||(t[20]=g('<p>起初我有點懷疑，因為我已經對 R 掌握得不錯了，但後來我發現你可以簡單地將 H2o 作為 R 庫導入。H2o 將大多數 R 函數替換為其自己的並行化函數，以減少處理時間（不再需要 <code>doParallel</code> 調用），並且使用“外部”服務端來運行，而不是直接調用 R。</p><p><img src="https://veronneau.org/media/blog/2018-03-14/h2o_model.png" alt="H2o Flow gradient boosting model" title="H2o Flow gradient boosting model"></p><p>直到我真正在實際中開始在 H2o 中使用 R 時，我對這種情況都非常滿意。我在使用非常大的資料庫時，庫變得笨重，我幾乎不能做任何有用得事情。大多數時候，我最後只是得到一個很長的 Java 回溯調用。</p><p>我相信正確地將 H2o 作為一個庫使用將非常強大，但可惜的是，它似乎在我的 R 技能中無效。</p><p><img src="https://veronneau.org/media/blog/2018-03-14/h2o_var_importance.png" alt="H2o Flow variable importance weights" title="H2o Flow variable importance weights"></p><p>我生了一整天的氣 —— 無法實現我想做的事 —— 直到我意識到 H2o 有一個名為 Flow 的 WebUI。我通常不喜歡使用 web 來完成重要的工作，比如編寫代碼，但是 Flow 簡直太不可思議了。</p><p>自動繪圖功能，運行資源密集模型時集成 ETA（預計剩餘時間），每個模型參數的描述（這些參數甚至會根據您熟悉的統計模型分成不同部分），Flow 似乎擁有所有功能。我很快就能夠運行 3 種基本的機器學習模型並獲得實際可解釋的結果。</p><p>所以，如果你一直渴望使用最先進的機器學習模型分析非常大的資料庫，我會推薦使用 H2o。首先嚐試使用 Flow，而不是 Python 或 R 的鈎子，來看看它能做什麼。</p><p>唯一缺點是，H2o 是用 Java 編寫的，並依賴 Java 1.7 來運行。並且需要警告的是：它需要非常強大的處理器和大量的內存。即使有 10 個可用的內核和 10Gb 的 RAM，我可憐的服務器也苦苦掙扎了一段時間。</p><hr>',10)),n("p",null,[t[6]||(t[6]=o("via: ",-1)),i(e,{href:"https://veronneau.org/playing-with-water.html"},{default:r(()=>[...t[5]||(t[5]=[o("https://veronneau.org/playing-with-water.html",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=o("作者：",-1)),i(e,{href:"https://veronneau.org/"},{default:r(()=>[...t[7]||(t[7]=[o("Louis-Philippe Véronneau",-1)])]),_:1}),t[11]||(t[11]=o(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:r(()=>[...t[8]||(t[8]=[o("geekpi",-1)])]),_:1}),t[12]||(t[12]=o(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[9]||(t[9]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=o("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[13]||(t[13]=[o("LCTT",-1)])]),_:1}),t[16]||(t[16]=o(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:r(()=>[...t[14]||(t[14]=[o("Linux中國",-1)])]),_:1}),t[17]||(t[17]=o(" 榮譽推出",-1))])])}const x=l(d,[["render",m]]);export{C as __pageData,x as default};
